def main() -> int:
    parser = argparse.ArgumentParser(description="Compile the strict evidence status ledger for GTM T001–T100.")
    parser.add_argument("--spec", type=Path, default=DEFAULT_SPEC)
    args = parser.parse_args()
    spec_text = args.spec.read_text(encoding="utf-8")
    payload = compile_todo_execution_ledger(spec_text, EVIDENCE_MAP, project_root=ROOT)
    verify_todo_execution_ledger(payload)
    output = ROOT / "evidence/v10/gtm-100-todo-execution-ledger-v2.json"
    atomic_write_text(output, json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n")
    print(json.dumps({"output": str(output), "status_counts": payload["status_counts"], "completion_claim_allowed": payload["completion_claim_allowed"], "content_sha256": payload["content_sha256"]}, ensure_ascii=False, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
